-- =========================================================
-- Horta Comunitária — schema inicial (PostgreSQL / Supabase)
-- =========================================================
-- Convertido da V1 em MySQL. Diferenças principais:
--   * AUTO_INCREMENT      -> bigint generated by default as identity
--   * ENUM                -> text + CHECK (mais fácil de mudar depois)
--   * índices nas FKs     -> criados à mão (o PostgreSQL não cria sozinho)
--   * RLS ligado em todas as tabelas (obrigatório no Supabase, ver o fim do arquivo)

-- ---------------------------------------------------------
-- Tabelas base
-- ---------------------------------------------------------

create table especie (
    id               bigint generated by default as identity primary key,
    nome_popular     varchar(100) not null,
    nome_cientifico  varchar(150),
    descricao        text,
    constraint uq_especie_nome_popular unique (nome_popular)
);

create table canteiro (
    id             bigint generated by default as identity primary key,
    nome           varchar(100) not null,
    comprimento_m  numeric(6,2),
    largura_m      numeric(6,2),
    observacoes    text,
    constraint uq_canteiro_nome unique (nome),
    constraint ck_canteiro_medidas check (
        (comprimento_m is null or comprimento_m > 0) and
        (largura_m is null or largura_m > 0)
    )
);

create table praga (
    id         bigint generated by default as identity primary key,
    nome       varchar(100) not null,
    descricao  text,
    sintomas   text,
    constraint uq_praga_nome unique (nome)
);

-- ---------------------------------------------------------
-- Pessoas e grupos
-- ---------------------------------------------------------

create table pessoa (
    id        bigint generated by default as identity primary key,
    nome      varchar(150) not null,
    email     varchar(255),                 -- opcional: nem todo voluntário tem e-mail
    telefone  varchar(20)                   -- só dígitos, com DDD. Ex.: 84999998888
);

-- o mesmo e-mail não pode aparecer em duas pessoas (sem diferenciar maiúsculas)
create unique index uq_pessoa_email on pessoa (lower(email));

create table grupo (
    id           bigint generated by default as identity primary key,
    nome         varchar(100) not null,
    descricao    text,
    canteiro_id  bigint,                    -- canteiro que o grupo cuida (NULL = ainda sem canteiro)
    constraint uq_grupo_nome unique (nome),
    -- um canteiro pertence a no máximo um grupo
    constraint uq_grupo_canteiro unique (canteiro_id),
    constraint fk_grupo_canteiro
        foreign key (canteiro_id) references canteiro (id)
        on delete set null
);

-- N:N: um grupo tem várias pessoas e uma pessoa pode participar de mais de um grupo
create table grupo_pessoa (
    grupo_id   bigint not null,
    pessoa_id  bigint not null,
    primary key (grupo_id, pessoa_id),
    constraint fk_grupo_pessoa_grupo
        foreign key (grupo_id) references grupo (id)
        on delete cascade,
    constraint fk_grupo_pessoa_pessoa
        foreign key (pessoa_id) references pessoa (id)
        on delete cascade
);

create index idx_grupo_pessoa_pessoa on grupo_pessoa (pessoa_id);

-- ---------------------------------------------------------
-- Planta (instância) e infestações
-- ---------------------------------------------------------

create table planta (
    id                     bigint generated by default as identity primary key,
    especie_id             bigint not null,
    canteiro_id            bigint,          -- nem toda planta está em canteiro
    localizacao_descricao  varchar(255),    -- ex.: "vaso na janela da sala 3"
    data_plantio           date,
    status                 text not null default 'ativa',
    constraint ck_planta_status
        check (status in ('ativa', 'colhida', 'morta', 'removida')),
    constraint fk_planta_especie
        foreign key (especie_id) references especie (id)
        on delete restrict,
    constraint fk_planta_canteiro
        foreign key (canteiro_id) references canteiro (id)
        on delete set null
);

create index idx_planta_especie  on planta (especie_id);
create index idx_planta_canteiro on planta (canteiro_id);

create table planta_praga (
    id               bigint generated by default as identity primary key,
    planta_id        bigint not null,
    praga_id         bigint not null,
    data_observacao  date not null,
    data_resolucao   date,                  -- NULL = infestação ainda ativa
    severidade       text,
    observacoes      text,
    -- necessário para a FK composta de aplicacao_planta
    constraint uq_planta_praga_id_planta unique (id, planta_id),
    constraint ck_planta_praga_severidade
        check (severidade is null or severidade in ('leve', 'moderada', 'grave')),
    constraint ck_planta_praga_datas
        check (data_resolucao is null or data_resolucao >= data_observacao),
    constraint fk_planta_praga_planta
        foreign key (planta_id) references planta (id)
        on delete cascade,
    constraint fk_planta_praga_praga
        foreign key (praga_id) references praga (id)
        on delete restrict
);

create index idx_planta_praga_planta on planta_praga (planta_id);
create index idx_planta_praga_praga  on planta_praga (praga_id);

-- ---------------------------------------------------------
-- Pastas, receitas e aplicações
-- ---------------------------------------------------------

create table pasta (
    id           bigint generated by default as identity primary key,
    nome         varchar(100) not null,
    descricao    text,
    modo_de_uso  text,
    constraint uq_pasta_nome unique (nome)
);

create table ingrediente (
    id    bigint generated by default as identity primary key,
    nome  varchar(100) not null,
    constraint uq_ingrediente_nome unique (nome)
);

create table pasta_ingrediente (
    pasta_id        bigint not null,
    ingrediente_id  bigint not null,
    quantidade      numeric(10,2) not null,
    unidade         varchar(20) not null,   -- g, ml, colher de sopa, dente...
    primary key (pasta_id, ingrediente_id),
    constraint ck_pasta_ing_quantidade check (quantidade > 0),
    constraint fk_pasta_ing_pasta
        foreign key (pasta_id) references pasta (id)
        on delete cascade,
    constraint fk_pasta_ing_ingrediente
        foreign key (ingrediente_id) references ingrediente (id)
        on delete restrict
);

create index idx_pasta_ingrediente_ing on pasta_ingrediente (ingrediente_id);

create table aplicacao_pasta (
    id                bigint generated by default as identity primary key,
    pasta_id          bigint not null,
    data_aplicacao    date not null,
    quantidade_usada  varchar(50),          -- texto livre: "1 litro", "2 borrifadas"
    observacoes       text,
    constraint fk_aplicacao_pasta
        foreign key (pasta_id) references pasta (id)
        on delete restrict
);

create index idx_aplicacao_pasta on aplicacao_pasta (pasta_id);
create index idx_aplicacao_data  on aplicacao_pasta (data_aplicacao);

create table aplicacao_planta (
    aplicacao_id     bigint not null,
    planta_id        bigint not null,
    planta_praga_id  bigint,                -- infestação que a aplicação tentava combater
    primary key (aplicacao_id, planta_id),
    constraint fk_apl_pl_aplicacao
        foreign key (aplicacao_id) references aplicacao_pasta (id)
        on delete cascade,
    constraint fk_apl_pl_planta
        foreign key (planta_id) references planta (id)
        on delete cascade,
    -- garante que a infestação informada pertence à MESMA planta
    -- (com planta_praga_id NULL a verificação é ignorada: MATCH SIMPLE)
    constraint fk_apl_pl_planta_praga
        foreign key (planta_praga_id, planta_id)
        references planta_praga (id, planta_id)
        on delete restrict
);

create index idx_aplicacao_planta_planta on aplicacao_planta (planta_id);
create index idx_aplicacao_planta_praga  on aplicacao_planta (planta_praga_id);

-- ---------------------------------------------------------
-- Segurança (Row Level Security)
-- ---------------------------------------------------------
-- No Supabase, o navegador fala direto com o banco usando a chave pública.
-- Sem RLS, qualquer pessoa com essa chave leria e apagaria tudo.
--
-- Regra inicial (simples, a ajustar quando houver login de verdade):
--   * visitante (anon):   só LÊ o catálogo — espécies, pragas, canteiros, pastas e receitas
--   * logado (authenticated): lê e escreve em tudo
--   * pessoa, grupo e grupo_pessoa NÃO são públicos (têm e-mail e telefone)

alter table especie           enable row level security;
alter table canteiro          enable row level security;
alter table praga             enable row level security;
alter table pessoa            enable row level security;
alter table grupo             enable row level security;
alter table grupo_pessoa      enable row level security;
alter table planta            enable row level security;
alter table planta_praga      enable row level security;
alter table pasta             enable row level security;
alter table ingrediente       enable row level security;
alter table pasta_ingrediente enable row level security;
alter table aplicacao_pasta   enable row level security;
alter table aplicacao_planta  enable row level security;

-- acesso de quem está logado: tudo
do $$
declare
    t text;
begin
    foreach t in array array[
        'especie', 'canteiro', 'praga', 'pessoa', 'grupo', 'grupo_pessoa',
        'planta', 'planta_praga', 'pasta', 'ingrediente', 'pasta_ingrediente',
        'aplicacao_pasta', 'aplicacao_planta'
    ] loop
        execute format('grant select, insert, update, delete on %I to authenticated', t);
        execute format(
            'create policy %I on %I for all to authenticated using (true) with check (true)',
            t || '_logado_tudo', t
        );
    end loop;
end $$;

-- leitura pública do catálogo
do $$
declare
    t text;
begin
    foreach t in array array[
        'especie', 'canteiro', 'praga', 'pasta', 'ingrediente', 'pasta_ingrediente'
    ] loop
        execute format('grant select on %I to anon', t);
        execute format(
            'create policy %I on %I for select to anon using (true)',
            t || '_publico_le', t
        );
    end loop;
end $$;
